/* HEXA BATTLEGROUNDS setup — PART 64 OF 84. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-bomb-24', 'bomb', 'mission', 'Bomb Defusal', 'game', 1, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Yellow, Red, Green, Blue, Red.\nSerial number: SR27Z9.  LED: GREEN.","game":{"type":"bomb","wires":["yellow","red","green","blue","red"],"serial":"SR27Z9","led":"green"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there are no RED wires at all, cut the wire just ABOVE the last one — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["5"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'yellow,red,green,blue,red · SR27Z9 · green → more than one red → last red → wire 5', null, 25, 'published'), ('mission-bomb-25', 'bomb', 'mission', 'Bomb Defusal', 'game', 1, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Yellow, White, Blue, Yellow, Yellow.\nSerial number: SR51Z4.  LED: RED.","game":{"type":"bomb","wires":["yellow","white","blue","yellow","yellow"],"serial":"SR51Z4","led":"red"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there is a WHITE wire and the LED is RED, cut the white wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["2"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'yellow,white,blue,yellow,yellow · SR51Z4 · red → override: If there is a WHITE wire and the LED is RED, cut the white wire — ignore the manual. → wire 2', null, 25, 'published'), ('mission-bomb-26', 'bomb', 'mission', 'Bomb Defusal', 'game', 2, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Blue, Red, Red, Green.\nSerial number: HX66Z4.  LED: RED.","game":{"type":"bomb","wires":["blue","red","red","green"],"serial":"HX66Z4","led":"red"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If the serial number contains the digit 7, cut the THIRD wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["3"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'blue,red,red,green · HX66Z4 · red → more than one red → last red → wire 3', null, 25, 'published'), ('mission-bomb-27', 'bomb', 'mission', 'Bomb Defusal', 'game', 1, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Black, Blue, Green, Green.\nSerial number: HX73A1.  LED: RED.","game":{"type":"bomb","wires":["black","blue","green","green"],"serial":"HX73A1","led":"red"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there are exactly two BLACK wires, cut the FIRST black wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["2"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'black,blue,green,green · HX73A1 · red → serial ends odd and there is blue → first blue → wire 2', null, 25, 'published'), ('mission-bomb-28', 'bomb', 'mission', 'Bomb Defusal', 'game', 1, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Black, Blue, White, Black, Blue.\nSerial number: OM92A3.  LED: BLUE.","game":{"type":"bomb","wires":["black","blue","white","black","blue"],"serial":"OM92A3","led":"blue"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If the LED is BLUE and the first wire is YELLOW, cut the LAST wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["2"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'black,blue,white,black,blue · OM92A3 · blue → serial ends odd and there is blue → first blue → wire 2', null, 25, 'published'), ('mission-bomb-29', 'bomb', 'mission', 'Bomb Defusal', 'game', 2, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Red, Red, Red, Blue, Green, White.\nSerial number: SR71A4.  LED: GREEN.","game":{"type":"bomb","wires":["red","red","red","blue","green","white"],"serial":"SR71A4","led":"green"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there are no RED wires at all, cut the wire just ABOVE the last one — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["3"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'red,red,red,blue,green,white · SR71A4 · green → more than one red → last red → wire 3', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();
